INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist eine 1:1-Beziehung in Datenbanken immer zwingend erforderlich?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig vom Datenmodell"}, {"text": "Ja", "correct": false, "because": "Nicht universell nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Beziehung beschreibt eine Tabelle "Kunden" zu "Bestellungen"?', 3, '[{"text": "1:n", "correct": true, "because": "Ein Kunde hat viele Bestellungen"}, {"text": "n:m", "correct": false, "because": "Braucht Zwischentabelle"}, {"text": "1:1", "correct": false, "because": "Zu restriktiv"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Beziehungen passen zu "Studenten" und "Kurse"?', 5, '[{"text": "n:m", "correct": true, "because": "Mehrere Studenten in mehreren Kursen"}, {"text": "1:n", "correct": false, "because": "Zu eingeschränkt"}, {"text": "1:1", "correct": false, "because": "Nicht realistisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) 1:n braucht einen Fremdschlüssel. b) n:m braucht eine Zwischentabelle.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "Technisch korrekt umgesetzt"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch richtig"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist auch richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beide sind korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Modellierung einer 1:n-Beziehung?', 4, '[{"text": "Fremdschlüssel", "correct": false, "because": "Verknüpfung essenziell"}, {"text": "Primärschlüssel", "correct": false, "because": "Identifikation nötig"}, {"text": "Tabellenfarbe", "correct": true, "because": "Irrelevant für Beziehung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine n:m-Beziehung ohne Zwischentabelle geht?', 2, '[{"text": "Nein", "correct": true, "because": "Verknüpfung erfordert Extra-Tabelle"}, {"text": "Ja", "correct": false, "because": "Technisch nicht umsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie setze ich eine Beziehung zwischen "Mitarbeiter" und "Abteilung" um?', 3, '[{"text": "1:n", "correct": true, "because": "Ein Mitarbeiter in einer Abteilung"}, {"text": "n:m", "correct": false, "because": "Zu komplex"}, {"text": "1:1", "correct": false, "because": "Zu restriktiv"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente brauche ich für eine n:m-Beziehung?', 5, '[{"text": "Zwischentabelle", "correct": true, "because": "Verknüpft beide Seiten"}, {"text": "Fremdschlüssel", "correct": true, "because": "Referenziert Primärschlüssel"}, {"text": "Unique Constraints", "correct": false, "because": "Optional, nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) 1:1-Beziehungen sind selten. b) Sie erhöhen die Performance. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Performance nicht garantiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist kontextabhängig"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einer 1:1-Beziehung unwichtig?', 4, '[{"text": "Primärschlüssel", "correct": false, "because": "Identifikation nötig"}, {"text": "Fremdschlüssel", "correct": false Bedeutet "correct": false, "because": "Verknüpfung essenziell"}, {"text": "Indexgröße", "correct": true, "because": "Sekundär für Modellierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist eine 1:n-Beziehung bidirektional?', 2, '[{"text": "Nein", "correct": true, "because": "Nur eine Richtung referenziert"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend umgekehrt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Beziehung wähle ich für "Person" und "Ausweis"?', 4, '[{"text": "1:1", "correct": true, "because": "Eine Person, ein Ausweis"}, {"text": "1:n", "correct": false, "because": "Zu viele Ausweise"}, {"text": "n:m", "correct": false, "because": "Zu komplex"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass n:m-Beziehungen immer langsam sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Hängt von Optimierung ab"}, {"text": "Ja", "correct": false, "because": "Nicht zwangsläufig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Modellierung?', 3, '[{"text": "Klarheit der Beziehungen", "correct": true, "because": "Verständnis fördern"}, {"text": "Minimale Tabellen", "correct": false, "because": "Kann Normalisierung stören"}, {"text": "Schnelle Abfragen", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) 1:1 kann durch Tabellenfusion ersetzt werden. b) n:m ist immer komplex.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "n:m kann optimiert werden"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht immer wahr"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile hat eine 1:n-Beziehung?', 5, '[{"text": "Einfache Abfragen", "correct": true, "because": "Direkte Referenz"}, {"text": "Datenkonsistenz", "correct": true, "because": "Weniger Redundanz"}, {"text": "Hohe Flexibilität", "correct": false, "because": "Eingeschränkt durch Richtung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einer n:m-Beziehung unwichtig?', 3, '[{"text": "Zwischentabelle", "correct": false, "because": "Essenziell für Verknüpfung"}, {"text": "Fremdschlüssel", "correct": false, "because": "Notwendig"}, {"text": "Tabellenname", "correct": true, "because": "Nur Konvention"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann eine 1:1-Beziehung redundant sein?', 3, '[{"text": "Ja", "correct": true, "because": "Wenn Daten zusammengeführt werden könnten"}, {"text": "Nein", "correct": false, "because": "Kontextabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine n:m-Beziehung für einfache Daten passt?', 2, '[{"text": "Nein", "correct": true, "because": "Zu komplex für Basics"}, {"text": "Ja", "correct": false, "because": "Überdimensioniert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Struktur wähle ich für "Projekte" und "Mitarbeiter"?', 4, '[{"text": "n:m", "correct": true, "because": "Mehrere Mitarbeiter an mehreren Projekten"}, {"text": "1:n", "correct": false, "because": "Zu restriktiv"}, {"text": "1:1", "correct": false, "because": "Unrealistisch"}]');